            for x in [-270,270]:
                blocked=any(abs(z-b)<20 for b in [-100,60]) and 1<=row<=4
                if not blocked:cells.add((x,z))
        st.append(line_cells(cells,-24*(row+1),TAN if row else STONE,f'wall-{row}'))
